const harness = (onConnect?: (session: ChatSession) => void, sessionStoreOverride?: SessionStore) => {
  const sessionStore =
    sessionStoreOverride ??
    ({
      create: (sessionId: string, userId: string | number): ChatSession => ({sessionId, userId, entries: []}),
      delete: () => true,
    } as unknown as SessionStore);

  const hal = createServer({
    app: (() => undefined) as unknown as Express,
    wsAuth: jest.fn() as unknown as WsAuthenticator,
    sessionStore,
    orchestrator: {} as ChatOrchestrator,
    onConnect,
  });

  const sent: string[] = [];
  const listeners = new Map<string, (...args: unknown[]) => void>();
  const ws = {
    userId: 'u1',
    isAlive: true,
    send: (raw: string) => void sent.push(raw),
    on: (event: string, listener: (...args: unknown[]) => void) => void listeners.set(event, listener),
    // The handler pauses the socket across an awaited create and resumes once its listeners are attached.
    pause: () => undefined,
    resume: () => undefined,
    close: () => undefined,
  } as unknown as ExtWebSocket;

  return {hal, ws, sent, listeners};
};

describe('createServer hook wiring', () => {
  it('forwards onConnect to the connection handler', async () => {
    const seen: ChatSession[] = [];
    const {hal, ws} = harness(session => void seen.push(session));

    hal.wss.emit('connection', ws);
    await settle();
    hal.wss.emit('close');

    expect(seen.length).toBe(1);
  });

  it('accepts a server configured without either hook', async () => {
    const {hal, ws} = harness();

    hal.wss.emit('connection', ws);
    await settle();
    hal.wss.emit('close');

    expect(hal.wss.listenerCount('connection')).toBe(1);
  });

  it('forwards sessionStore to the message handler so list_sessions queries the configured store', async () => {
    const asked: Array<string | number> = [];
    const store = {
      create: (sessionId: string, userId: string | number): ChatSession => ({sessionId, userId, entries: []}),
      delete: () => true,
      listFor: (userId: string | number) => {
        asked.push(userId);
        return [
          {
            sessionId: 's-1',
            createdAt: new Date('2026-01-01T00:00:00.000Z'),
            updatedAt: new Date('2026-01-02T00:00:00.000Z'),
            entryCount: 3,
          },
        ];
      },
    } as unknown as SessionStore;
    const {hal, ws, sent, listeners} = harness(undefined, store);

    hal.wss.emit('connection', ws);
    await settle();
    listeners.get('message')?.(JSON.stringify({type: 'list_sessions'}));
    await settle();
    hal.wss.emit('close');

    expect({asked, last: JSON.parse(sent.at(-1) ?? '{}')}).toEqual({
      asked: ['u1'],
      last: {
        type: 'session_list',
        sessions: [
          {
            sessionId: 's-1',
            createdAt: '2026-01-01T00:00:00.000Z',
            updatedAt: '2026-01-02T00:00:00.000Z',
            entryCount: 3,
          },
        ],
      },
    });
  });
});

